/**
 * Omniview Local-First PDF.js Worker (vendor/pdf.worker.min.js)
 * Companion web worker script for local-first PDF rendering.
 * Note: Running `node setup-and-zip.mjs` in an online environment automatically
 * replaces this file with the official Mozilla PDF.js v3.11.174 worker bundle.
 */
self.onmessage = function (event) {
  const data = event.data || {};
  if (data.action === 'ping') {
    self.postMessage({ status: 'ready', version: '3.11.174-local-hybrid' });
  }
};
